import { describe, expect, it } from "@jest/globals";

import fixture from "./fixtures/python-canonical.json";
import {
  briefingInputHash,
  canonicalJson,
  sha256Hex,
} from "../swell-briefing-hash";

/**
 * The worker hashes in Python and the server revalidates in TypeScript. If the
 * two serializers disagree by a single byte every upload is rejected, so these
 * cases are generated by the worker's own `canonical()` and checked here rather
 * than being written by hand on this side.
 */
describe("canonicalJson against the worker's Python output", () => {
  const cases = fixture as unknown as Record<string, { canonical: string; sha256: string }>;

  for (const name of [
    "simple",
    "nested_sorted",
    "unicode",
    "numbers",
    "nulls",
    "escapes",
    "empty",
    "briefing_like",
  ]) {
    it(`matches Python byte for byte: ${name}`, () => {
      const expected = cases[name];
      const value = JSON.parse(expected.canonical);
      expect(canonicalJson(value)).toBe(expected.canonical);
      expect(sha256Hex(canonicalJson(value))).toBe(expected.sha256);
    });
  }

  it("hashes a snapshot with inputHash removed, as the worker does", () => {
    const { snapshot, inputHash } = (fixture as unknown as {
      input_hash_excludes_field: { snapshot: Record<string, unknown>; inputHash: string };
    }).input_hash_excludes_field;

    expect(briefingInputHash(snapshot)).toBe(inputHash);
    // The excluded field must not influence the result.
    expect(briefingInputHash({ ...snapshot, inputHash: "something-else" })).toBe(inputHash);
  });
});

describe("canonicalJson refuses what Python cannot reproduce", () => {
  it("sorts object keys by code point", () => {
    expect(canonicalJson({ b: 1, a: 2, A: 3 })).toBe('{"A":3,"a":2,"b":1}');
  });

  it("drops undefined members rather than emitting a key", () => {
    expect(canonicalJson({ a: undefined, b: 1 })).toBe('{"b":1}');
  });

  it("rejects non-finite numbers instead of writing null", () => {
    expect(() => canonicalJson({ a: Number.NaN })).toThrow(/not representable/);
    expect(() => canonicalJson({ a: Number.POSITIVE_INFINITY })).toThrow(/not representable/);
  });

  it("rejects negative zero, which Python writes as -0.0", () => {
    expect(() => canonicalJson({ a: -0 })).toThrow(/negative zero/);
  });

  it("rejects a circular reference rather than hanging", () => {
    const loop: Record<string, unknown> = {};
    loop.self = loop;
    expect(() => canonicalJson(loop)).toThrow(/circular/);
  });
});
